"""Unit tests for the formal inference groups generated by data_prep."""

from __future__ import annotations

import sys
from pathlib import Path

import numpy as np
import pandas as pd
import yaml


REPO_ROOT = Path("/home/maomao/prediction-NN-2")
if str(REPO_ROOT) not in sys.path:
    sys.path.insert(0, str(REPO_ROOT))

from prediction_nn2.data_prep import DataPrepConfig, prepare_npz_splits


def _write_mock_day(stock1m_dir: Path, trade_date: int) -> None:
    """Write one tiny stock1m feather day with two stocks and 25 minutes."""
    # Build one deterministic minute panel that satisfies feature and label requirements.
    trade_day = pd.Timestamp(str(trade_date))
    rows: list[dict[str, object]] = []
    for stock_code in [1, 2]:
        for minute_index in range(25):
            ts = trade_day + pd.Timedelta(hours=9, minutes=30 + minute_index)
            base = 10.0 + 0.5 * float(stock_code) + 0.01 * float(minute_index)
            rows.append(
                {
                    "StockCode": int(stock_code),
                    "DateTime": ts,
                    "Open": float(base),
                    "Close": float(base + 0.01),
                    "High": float(base + 0.02),
                    "Low": float(base - 0.02),
                    "Vol": float(100.0 + minute_index),
                    "Amount": float((100.0 + minute_index) * base),
                    "Date": int(trade_date),
                    "MinuteIndex": int(minute_index),
                }
            )

    # Persist the tiny day panel under the stock1m year/date layout.
    year_dir = Path(stock1m_dir) / str(int(trade_date) // 10000)
    year_dir.mkdir(parents=True, exist_ok=True)
    pd.DataFrame(rows).to_feather(year_dir / f"{int(trade_date)}.feather")


def test_prepare_npz_splits_builds_formal_inference_groups_without_label_filter(tmp_path: Path):
    """Ensure the inference groups use feature availability instead of label-based samples."""
    # Write three tiny trading days so train/val/test each get one day.
    stock1m_dir = Path(tmp_path) / "stock1m"
    for trade_date in [20210104, 20210105, 20210106]:
        _write_mock_day(stock1m_dir, int(trade_date))

    # Run data prep with train-time sampling enabled and inference split generation enabled.
    out_dir = Path(tmp_path) / "artifacts"
    config = DataPrepConfig(
        stock1m_dir=stock1m_dir,
        out_dir=out_dir,
        start_trade_date=20210104,
        end_trade_date=20210106,
        train_days=1,
        val_days=1,
        test_days=1,
        seed=7,
        horizon_minutes=10,
        label_entry_lag_minutes=1,
        sample_stocks_per_minute=1,
        use_cross_sectional_gaussianize=False,
        use_ret_signed_log1p=True,
        use_heavy_tanh=True,
        heavy_tanh_c=3.0,
        add_is_zero_features=False,
        include_session_id=False,
        include_inference_splits=True,
        norm_fit_scope="train_only",
        label_norm="pooled_zscore",
        label_norm_fit_scope="train_only",
        days_per_call=100,
        workers=1,
    )
    prep = prepare_npz_splits(config)

    # Load meta.yaml and the inference-test placeholder labels for direct semantic checks.
    meta_path = Path(prep["meta_path"])
    meta = yaml.safe_load(meta_path.read_text(encoding="utf-8"))
    groups = dict(meta["storage"]["groups"])
    inference_test_rows = int(groups["inference_test"]["rows"])
    inference_test_y_path = meta_path.parent / str(groups["inference_test"]["y"])
    inference_test_y = np.memmap(inference_test_y_path, mode="r", dtype=np.float32, shape=(int(inference_test_rows), 1))

    # Require the inference groups to exist and inference_test to exceed sampled test rows.
    assert int(prep["inference_test_rows"]) == int(inference_test_rows)
    assert int(inference_test_rows) > int(groups["test"]["rows"])
    assert int(groups["inference_train"]["rows"]) > 0
    assert int(groups["inference_val"]["rows"]) > 0
    assert list(meta["dates"]["inference_test"]) == [20210106]
    assert dict(meta["inference_contracts"]["inference_test"]) == {
        "type": "feature_only_inference_split",
        "group": "inference_test",
        "source_split": "test",
        "dates": [20210106],
        "uses_label_filter": False,
        "uses_sampling": False,
        "target_placeholder": "nan",
    }

    # Require inference placeholder labels to stay NaN so misuse is visible immediately.
    assert bool(np.isnan(np.asarray(inference_test_y)).all())
